'use client'

import { useState } from 'react'
import TitleBar from './components/TitleBar'
import Tabs from './components/Tabs'
import HistoryPanel from './components/HistoryPanel'

export default function Home() {
  // Controla qual aba está ativa
  const [activeTab, setActiveTab] = useState<'home' | 'settings'>('home')
  // Controla se o painel de histórico está expandido
  const [historyOpen, setHistoryOpen] = useState(false)

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-gray-900 dark:to-gray-800 flex flex-col items-center">
      {/* Barra de título customizada */}
      <TitleBar />

      {/* Conteúdo principal centralizado */}
      <div className="w-full max-w-3xl flex-1 flex flex-col mt-4">
        {/* Abas Home/Settings */}
        <Tabs activeTab={activeTab} onTabChange={setActiveTab} />

        {/* Painel de histórico retrátil */}
        <HistoryPanel open={historyOpen} onToggle={() => setHistoryOpen(v => !v)} />
      </div>
    </div>
  )
}
